from collections import defaultdict
from functools import lru_cache

def maxScoreWords(words, letters, score):
    letter_counts = defaultdict(int)
    for l in letters:
        letter_counts[l] += 1

    @lru_cache(maxsize=None)
    def backtrack(index, remaining_counts):
        if index == len(words):
            return 0
        word = words[index]
        word_counts = defaultdict(int)
        word_score = 0
        valid = True
        for c in word:
            word_counts[c] += 1
            word_score += score[ord(c) - ord('a')]
            if word_counts[c] > remaining_counts[c]:
                valid = False
                break
        if valid:
            new_counts = tuple(remaining_counts[c] - word_counts[c] for c in 'abcdefghijklmnopqrstuvwxyz')
            option1 = word_score + backtrack(index + 1, new_counts)
        else:
            option1 = 0
        option2 = backtrack(index + 1, remaining_counts)
        return max(option1, option2)

    initial_counts = tuple(letter_counts[c] for c in 'abcdefghijklmnopqrstuvwxyz')
    return backtrack(0, initial_counts)
